import frappe
from frappe import _
from frappe.utils import flt
from qorg.qorg.shared_cost_allocation.reporting import in_selected,apply_view,chart_by,summary

def execute(filters=None):
 f=frappe._dict(filters or {});runs=frappe.get_all("Shared Cost Allocation Run",filters={"company":f.company,"allocation_category":"Indirect Cost Recovery","posting_date":["between",[f.from_date,f.to_date]]},fields=["name","posting_date","allocation_rule","run_type","eligible_base_amount","indirect_rate_applied","recovery_cap_applied","prior_recovery_amount","adjustment_amount","allocated_amount","unallocated_amount","journal_entry","reconciliation_status"]);rows=[]
 for run in runs:
  if not in_selected(run.run_type,f,"run_type"):continue
  for e in frappe.get_all("Shared Cost Allocation Entry",filters={"parent":run.name},fields=["project","funding_agreement","donor","budget_line","allocated_amount","eligibility_status","exception_message"]):
   if not in_selected(e.project,f,"project") or not in_selected(e.donor,f,"donor") or not in_selected(e.funding_agreement,f,"funding_agreement"):continue
   rows.append({"run":run.name,**run,**e})
 columns=[{"label":_("Run"),"fieldname":"run","fieldtype":"Link","options":"Shared Cost Allocation Run","width":160,"sticky":1},{"label":_("Project"),"fieldname":"project","fieldtype":"Link","options":"Project","width":160,"sticky":1},{"label":_("Date"),"fieldname":"posting_date","fieldtype":"Date","width":95},{"label":_("Donor"),"fieldname":"donor","fieldtype":"Link","options":"Donor","width":145},{"label":_("Funding Agreement"),"fieldname":"funding_agreement","fieldtype":"Link","options":"Funding Agreement","width":175},{"label":_("Budget Line"),"fieldname":"budget_line","fieldtype":"Link","options":"Budget Line","width":160},{"label":_("Eligible Base"),"fieldname":"eligible_base_amount","fieldtype":"Currency","width":120},{"label":_("Rate %"),"fieldname":"indirect_rate_applied","fieldtype":"Percent","width":80},{"label":_("Cap"),"fieldname":"recovery_cap_applied","fieldtype":"Currency","width":110},{"label":_("Prior Recovery"),"fieldname":"prior_recovery_amount","fieldtype":"Currency","width":120},{"label":_("Adjustment"),"fieldname":"adjustment_amount","fieldtype":"Currency","width":110},{"label":_("Recovered"),"fieldname":"allocated_amount","fieldtype":"Currency","width":120},{"label":_("Unallocated"),"fieldname":"unallocated_amount","fieldtype":"Currency","width":115},{"label":_("Reconciliation"),"fieldname":"reconciliation_status","width":110},{"label":_("Journal Entry"),"fieldname":"journal_entry","fieldtype":"Link","options":"Journal Entry","width":150},{"label":_("Exception"),"fieldname":"exception_message","width":240}]
 base=sum(flt(x.eligible_base_amount) for x in {x.run:x for x in rows}.values());recovered=sum(flt(x.allocated_amount) for x in rows);adjusted=sum(flt(x.adjustment_amount) for x in {x.run:x for x in rows}.values());exceptions=sum(1 for x in rows if x.eligibility_status!="Eligible")
 return apply_view(columns,f.view_mode),rows,None,chart_by(rows,"donor","allocated_amount",_("Recovered")),summary([(_("Eligible Base"),base,"Currency","Blue"),(_("Recovered"),recovered,"Currency","Green"),(_("Adjustments"),adjusted,"Currency","Orange"),(_("Exceptions"),exceptions,"Int","Red" if exceptions else "Green")]),1
